ate_size":30,"key_personnel":[{"name":"John Light","role":"Product","contribution":"Bitcoin scaling researcher and strategist."},{"name":"Trey Del Bonis","role":"Protocol Engineer","contribution":"Core development of the Bitcoin rollup architecture."},{"name":"Manish Bista & Aaron Feickert","role":"Research & Development","contribution":"Key contributors to the 1-of-N verifier for Bitcoin."}]},"founders":[{"name":"Simanta Gautam","role":"Co-founder & CEO","background":"MIT Alumnus; previously at SpaceX and Microsoft."},{"name":"Abishkar Chhetri","role":"Co-founder","background":"MIT Alumnus with a background in complex engineering systems."},{"name":"Liam Eagan","role":"Founding Cryptographer","background":"Former researcher at Blockstream; specialist in zero-knowledge proofs."}],"signal_interpretation":{"founder_signal_summary":"The Alpen Labs team lists 3 named leaders with complementary operating and technical depth.\n\nApproximate team scale / focus: 30.\n\nPer-founder roster (summary):\nSimanta Gautam — Co-founder & CEO — MIT Alumnus; previously at SpaceX and Microsoft.\nAbishkar Chhetri — Co-founder — MIT Alumnus with a background in complex engineering systems.\nLiam Eagan — Founding Cryptographer — Former researcher at Blockstream; specialist in zero-knowledge proofs.\n\nDiligence focus: verify prior operating scale (revenue / mandate), hiring velocity, domain-specific proof points, and cohesion between GTM and technical leads; cross-check claims against references and attributed public sources.","team_evidence":{"high_bar_previous_employers":"Prior employers and titles are listed per founder in the corpus.","technical_authority_proof":"Technical authority inferred from roles and prior companies.","team_cohesion_signals":"See founding team narrative in corpus."}}},"summary_text":"Simanta Gautam — Co-founder & CEO — MIT Alumnus; previously at SpaceX and Microsoft.\nAbishkar Chhetri — Co-founder — MIT Alumnus with a background in complex engineering systems.\n