INSERT INTO public.deal_pipeline_json_thesis_fit (deal_id, analysis_id, thesis_fit_json)
VALUES ('1a000000-0000-4000-8000-000000000002'::uuid, '1b000000-0000-4000-8000-000000000002'::uuid, $j${"overall_thesis_alignment_reasoning":"Tensec — thesis fit (historical corpus, invested).\n\nProblem (Small and Medium-sized Businesses (SMBs) are historically excluded from the sophisticated financ…): Small and Medium-sized Businesses (SMBs) are historically excluded from the sophisticated financial tools used by large enterprises.\n\nLegacy Infrastructure: Heavy reliance on 40-year-old SWIFT technology that is slow and opaque.\nComplexity: Global trade companies struggle to offer financial services to their partners due to 'Integration Hell.'\nInefficiency: High costs and weeks-long verification processes for international money movement.\n\nSolution direction: AI-Native Zero-Integration Platform\n\nContextual Finance: Embeds FX, cross-border payments, and transaction banking directly where global traders operate.\nZero-Integration: Allows companies to launch financial services for their clients without heavy engineering overhead.\nAI-Driven Compliance: Uses AI agents to cut risk assessment and verification times from weeks to minutes.\nRevenue Sharing Model: Enables partners to transform payment facilitation from a cost center into a profitable revenue stream.\n\nModernizing the $190 trillion cross-border market by flipping the banking model—empowering trade companies to act as their own financial hubs for their partners.\n\nInstitutional context: Seed financing profile ($12 Million (Seed Round, June 2025)); team and milestones are consistent with a venture-scale wedge and repeatable GTM.\n\nWhy this cleared the bar at the time: clear buyer pain, differentiated product narrative versus incumbents, and execution depth we could underwrite at the seed mark.","fit_summary":"Strong fit — Tensec is recorded as invested in the markdown corpus.","industry_evaluation":{"startup_industry":"Small and Medium-sized Businesses (SMBs) are historically excluded from the sophisticated financ…","score":8.2},"stage_evaluation":{"stage":"Seed","score":7.8},"funding_evaluation":{"funding":"$12 Million (Seed Round, June 2025)","score":8}}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET thesis_fit_json = EXCLUDED.thesis_fit_json;

