INSERT INTO public.deal_pipeline_json_problem_3c (deal_id, analysis_id, problem_quality_3c_json)
VALUES ('1a000000-0000-4000-8000-000000000003'::uuid, '1b000000-0000-4000-8000-000000000003'::uuid, $j${"summary_text":"AI models are inherently non-deterministic and 'shifty,' making traditional software testing methods (which expect a single correct answer) obsolete.\n\nThe Confidence Gap: Enterprises are afraid to deploy AI because they cannot predict when or why it will fail.\nVibe Checks: Most teams currently rely on manual, anecdotal testing rather than rigorous statistical data.\nNon-Stationarity: AI behavior changes over time due to data drift or upstream model updates without the developer's knowledge.","root_cause_depth":"AI models are inherently non-deterministic and 'shifty,' making traditional software testing methods (which expect a single correct answer) obsolete.","economic_gravity":"AI models are inherently non-deterministic and 'shifty,' making traditional software testing methods (which expect a single correct answer) obsolete.\n\nThe Confidence Gap: Enterprises are afraid to deploy AI because they cannot predict when or why it will fail.\nVibe Checks: Most teams currently rely on manual, anecdotal testing rather than rigorous statistical data.\nNon-Stationarity: AI behavior changes over time due to data drift or upstream model updates without the developer's knowledge.","structural_urgency":"AI models are inherently non-deterministic and 'shifty,' making traditional software testing methods (which expect a single correct answer) obsolete.\n\nThe Confidence Gap: Enterprises are afraid to deploy AI because they cannot predict when or why it will fail.\nVibe Checks: Most teams currently rely on manual, anecdotal testing rather than rigorous statistical data.\nNon-Stationarity: AI behavior changes over time due to data drift or upstream model updates without the developer's knowledge.","persona_clarity":null,"stated_problem_ref":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET problem_quality_3c_json = EXCLUDED.problem_quality_3c_json;

INSERT INTO public.deal_pipeline_json_solution_3d (deal_id, analysis_id, solution_defensibility_json)
VALUES ('1a000000-0000-4000-8000-000000000003'::uuid, '1b000000-0000-4000-8000-000000000003'::uuid, $j${"summary_text":"The Distributional AI Testing Platform\n\nStatistical Outlier Detection: Analyzes distributions of outputs rather than single data points to identify anomalies.\nAutomated Test Suggestions: Uses AI to recommend the best tests for a specific model's use case.\nAdaptive Calibration: Continuously adjusts test thresholds as the model evolves to prevent 'false alarm' fatigue.\nCI/CD Integration: Automatically blocks 'unreliable' model versions from being pushed to production.\n\nTransforming AI testing from a bottleneck into a scalable, automated process that allows enterprises to ship reliable AI products with the same confidence they have in traditional software.","moat_type":null,"replication_difficulty":null,"compounding_potential":null,"technical_moat_evidence":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET solution_defensibility_json = EXCLUDED.solution_defensibility_json;

