UPDATE public.deal_analyses SET raw_output = $j${"company_name":"Fibr AI","founded_year":2023,"headquarters":"San Francisco, CA","founders":[{"name":"Ankur \"AJ\" Goyal","role":"Co-founder & CEO","background":"Former enterprise software executive with deep experience in growth marketing and AI."},{"name":"Pritam Roy","role":"Co-founder & CPO","background":"Product leader specializing in high-scale enterprise platforms and user experience."}],"founding_team":{"key_expertise":"Comprised of veterans from enterprise software giants and marketing technology sectors.","focus":"Specialists in agentic AI, conversion rate optimization (CRO), and enterprise-grade compliance."},"traction":{"funding":{"total_funding":"$9.3 Million","latest_round":"$7.5 Million Seed (February 2026)","lead_investor":"Accel","participating_investors":["WillowTree Ventures","MVP Ventures","Fortune 100 Angel Operators"]},"business_metrics":["Secured 3-to-5 year contracts with Fortune 50 banks and global healthcare providers.","Reports an average of 28% higher ROI and 30% lower Customer Acquisition Cost (CAC) for early partners.","Successfully processed thousands of concurrent micro-experiments across high-traffic enterprise sites."]},"problem_statement":{"core_issue":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.","barriers":["Integration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.","Static Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.","Operational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns."]},"solution":{"primary_product":"Agentic Web Experience Layer","key_features":["Intelligent URLs: Every page acts as an autonomous agent that senses intent and reshapes itself in real-time.","Autonomous Experimentation: The platform generates hypotheses and runs parallel tests without manual coding.","Context-Aware Adaptation: Tailors content specifically for visitors coming from LLMs (like ChatGPT), social ads, or search queries.","Human-in-the-Loop Governance: Built-in approval workflows ensure AI-generated variants remain on-brand and compliant for regulated industries."],"value_proposition":"Transforming the website from a passive destination into an active, intelligent part of the growth stack that treats every visitor as an audience of one."},"parsing_json":{"company_overview":{"company_name":"Fibr AI"},"problem":{"problem_statement":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.\n\nIntegration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.\nStatic Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.\nOperational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns."},"solution":{"solution_summary":"Agentic Web Experience Layer\n\nIntelligent URLs: Every page acts as an autonomous agent that senses intent and reshapes itself in real-time.\nAutonomous Experimentation: The platform generates hypotheses and runs parallel tests without manual coding.\nContext-Aware Adaptation: Tailors content specifically for visitors coming from LLMs (like ChatGPT), social ads, or search queries.\nHuman-in-the-Loop Governance: Built-in approval workflows ensure AI-generated variants remain on-brand and compliant for regulated industries.\n\nTransforming the website from a passive destination into an active, intelligent part of the growth stack that treats every visitor as an audience of one."}},"thesis_fit_json":{"overall_thesis_alignment_reasoning":"Fibr AI — thesis fit (historical corpus, invested).\n\nProblem (The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to r…): The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.\n\nIntegration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.\nStatic Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.\nOperational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns.\n\nSolution direction: Agentic Web Experience Layer\n\nIntelligent URLs: Every page acts as an autonomous agent that senses intent and reshapes itself in real-time.\nAutonomous Experimentation: The platform generates hypotheses and runs parallel tests without manual coding.\nContext-Aware Adaptation: Tailors content specifically for visitors coming from LLMs (like ChatGPT), social ads, or search queries.\nHuman-in-the-Loop Governance: Built-in approval workflows ensure AI-generated variants remain on-brand and compliant for regulated industries.\n\nTransforming the website from a passive destination into an active, intelligent part of the growth stack that treats every visitor as an audience of one.\n\nInstitutional context: Seed financing profile ($7.5 Million Seed (February 2026) · $9.3 Million); team and milestones are consistent with a venture-scale wedge and repeatable GTM.\n\nWhy this cleared the bar at the time: clear buyer pain, differentiated product narrative versus incumbents, and execution depth we could underwrite at the seed mark.","fit_summary":"Strong fit — Fibr AI is recorded as invested in the markdown corpus.","industry_evaluation":{"startup_industry":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to r…","score":8.2},"stage_evaluation":{"stage":"Seed","score":7.8},"funding_evaluation":{"funding":"$7.5 Million Seed (February 2026) · $9.3 Million","score":8}},"founder_signal_json":{"per_founder":[{"name":"Ankur \"AJ\" Goyal","role":"Co-founder & CEO","background":"Former enterprise software executive with deep experience in growth marketing and AI.","founder_name":"Ankur \"AJ\" Goyal"},{"name":"Pritam Roy","role":"Co-founder & CPO","background":"Product leader specializing in high-scale enterprise platforms and user experience.","founder_name":"Pritam Roy"}],"collective":{"founding_team":{"key_expertise":"Comprised of veterans from enterprise software giants and marketing technology sectors.","focus":"Specialists in agentic AI, conversion rate optimization (CRO), and enterprise-grade compliance."},"founders":[{"name":"Ankur \"AJ\" Goyal","role":"Co-founder & CEO","background":"Former enterprise software executive with deep experience in growth marketing and AI."},{"name":"Pritam Roy","role":"Co-founder & CPO","background":"Product leader specializing in high-scale enterprise platforms and user experience."}],"signal_interpretation":{"founder_signal_summary":"The Fibr AI team lists 2 named leaders with complementary operating and technical depth.\n\nCollective expertise: Comprised of veterans from enterprise software giants and marketing technology sectors.\n\nPer-founder roster (summary):\nAnkur \"AJ\" Goyal — Co-founder & CEO — Former enterprise software executive with deep experience in growth marketing and AI.\nPritam Roy — Co-founder & CPO — Product leader specializing in high-scale enterprise platforms and user experience.\n\nDiligence focus: verify prior operating scale (revenue / mandate), hiring velocity, domain-specific proof points, and cohesion between GTM and technical leads; cross-check claims against references and attributed public sources.","team_evidence":{"high_bar_previous_employers":"Prior employers and titles are listed per founder in the corpus.","technical_authority_proof":"Technical authority inferred from roles and prior companies.","team_cohesion_signals":"Comprised of veterans from enterprise software giants and marketing technology sectors."}}},"summary_text":"Ankur \"AJ\" Goyal — Co-founder & CEO — Former enterprise software executive with deep experience in growth marketing and AI.\nPritam Roy — Co-founder & CPO — Product leader specializing in high-scale enterprise platforms and user experience.","founder_signal_summary":"The Fibr AI team lists 2 named leaders with complementary operating and technical depth.\n\nCollective expertise: Comprised of veterans from enterprise software giants and marketing technology sectors.\n\nPer-founder roster (summary):\nAnkur \"AJ\" Goyal — Co-founder & CEO — Former enterprise software executive with deep experience in growth marketing and AI.\nPritam Roy — Co-founder & CPO — Product leader specializing in high-scale enterprise platforms and user experience.\n\nDiligence focus: verify prior operating scale (revenue / mandate), hiring velocity, domain-specific proof points, and cohesion between GTM and technical leads; cross-check claims against references and attributed public sources."},"traction_signal_json":{"inferred_context":{"funding":{"total_funding":"$9.3 Million","latest_round":"$7.5 Million Seed (February 2026)","lead_investor":"Accel","participating_investors":["WillowTree Ventures","MVP Ventures","Fortune 100 Angel Operators"]},"business_metrics":["Secured 3-to-5 year contracts with Fortune 50 banks and global healthcare providers.","Reports an average of 28% higher ROI and 30% lower Customer Acquisition Cost (CAC) for early partners.","Successfully processed thousands of concurrent micro-experiments across high-traffic enterprise sites."]},"summary_text":"Funding: $7.5 Million Seed (February 2026) · $9.3 Million · Accel · Investors: WillowTree Ventures, MVP Ventures, Fortune 100 Angel Operators\nBusiness metrics:\n• Secured 3-to-5 year contracts with Fortune 50 banks and global healthcare providers.\n• Reports an average of 28% higher ROI and 30% lower Customer Acquisition Cost (CAC) for early 