INSERT INTO public.deal_pipeline_json_problem_3c (deal_id, analysis_id, problem_quality_3c_json)
VALUES ('1a000000-0000-4000-8000-000000000004'::uuid, '1b000000-0000-4000-8000-000000000004'::uuid, $j${"summary_text":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.\n\nIntegration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.\nStatic Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.\nOperational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns.","root_cause_depth":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.","economic_gravity":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.\n\nIntegration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.\nStatic Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.\nOperational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns.","structural_urgency":"The 'Personalization Gap': While digital ads are hyper-personalized, the websites they lead to remain static and generic.\n\nIntegration Hell: Traditional CRO tools (like Optimizely or Adobe Target) require heavy engineering and agency support to scale.\nStatic Destinations: CMS platforms were built to publish content, not to interpret real-time visitor intent or context.\nOperational Bottleneck: Manual A/B testing is too slow to keep up with the volume of modern, AI-driven marketing campaigns.","persona_clarity":null,"stated_problem_ref":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET problem_quality_3c_json = EXCLUDED.problem_quality_3c_json;

INSERT INTO public.deal_pipeline_json_solution_3d (deal_id, analysis_id, solution_defensibility_json)
VALUES ('1a000000-0000-4000-8000-000000000004'::uuid, '1b000000-0000-4000-8000-000000000004'::uuid, $j${"summary_text":"Agentic Web Experience Layer\n\nIntelligent URLs: Every page acts as an autonomous agent that senses intent and reshapes itself in real-time.\nAutonomous Experimentation: The platform generates hypotheses and runs parallel tests without manual coding.\nContext-Aware Adaptation: Tailors content specifically for visitors coming from LLMs (like ChatGPT), social ads, or search queries.\nHuman-in-the-Loop Governance: Built-in approval workflows ensure AI-generated variants remain on-brand and compliant for regulated industries.\n\nTransforming the website from a passive destination into an active, intelligent part of the growth stack that treats every visitor as an audience of one.","moat_type":null,"replication_difficulty":null,"compounding_potential":null,"technical_moat_evidence":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET solution_defensibility_json = EXCLUDED.solution_defensibility_json;

