VALUES ('1a000000-0000-4000-8000-000000000004'::uuid, '1b000000-0000-4000-8000-000000000004'::uuid, $j${"questions_first_order_json":{"critical_assumption_interrogation":[{"assumption":"Customers will pay and expand for Fibr AI's core wedge at venture-scale unit economics.","killer_questions":{"evidence":"What signed contracts or paid pilots prove budget and urgency for Fibr AI?","behavioral_proof":"What would we observe in customer usage that proves repeat, not one-off, adoption?","failure_boundary":"At what ARR or retention threshold would you declare the GTM hypothesis failed?","contradictory_signal":"What single metric trending wrong would force a strategy reset for Fibr AI?"}}],"linchpin_questions":{"real_world_evidence":"What third-party or customer-attributable proof de-risks Fibr AI's main claim?","structural_dependency_test":"Which single integration, partner, or regulatory dependency could stall Fibr AI if it slips?","market_contradiction":"What incumbent or substitute motion would make Fibr AI's wedge irrelevant in 18–24 months?"}},"questions_structural_json":{"dependency_chain_questions":{"weakest_link_verification":"Which step in Fibr AI's delivery chain (data, compliance, distribution) is least proven?","unvalidated_step_check":"What assumption in the sales or onboarding funnel has not been stress-tested at scale?","cascade_failure_test":"If the primary acquisition channel degrades, what is the fallback path to quota?"},"failure_mode_questions":["How does Fibr AI lose to a well-funded incumbent copying the feature set?","What breaks first if hiring or roadmap slips by two quarters?"],"conviction_delta_credibility_questions":["What would increase conviction in Fibr AI by two points on a 10-point scale in 90 days?"]}}$j$::jsonb)
