UPDATE public.deal_analyses SET raw_output = $j${"company_name":"FairPlay AI","founded_year":2020,"headquarters":"Los Angeles, CA","founders":[{"name":"Kareem Saleh","role":"Founder & CEO","background":"Former executive at Zest.ai and SoftCard; served in the Obama Administration managing international investment teams."},{"name":"John Merrill","role":"Co-founder & Principal Scientist","background":"Mathematician and AI expert; previously a lead scientist at Zest.ai and spent 15 years at Microsoft and Google building ML tools."}],"founding_team":{"key_personnel":[{"name":"Patrick Cadic","role":"COO","background":"Experienced operations leader in fintech and high-growth startups."},{"name":"Abby Hogan","role":"SVP of Legal Affairs","background":"Specialist in regulatory compliance and fair lending law."},{"name":"Mark Eberstein","role":"EVP of Data Science","background":"Expert in algorithmic fairness and statistical modeling."}],"team_composition":"The team includes veterans from Microsoft, Google, PayPal, and Goldman Sachs, specializing in AI safety, regulatory law, and consumer finance."},"traction":{"funding":{"total_funding":"$24.5 Million","latest_round":"$10 Million (February 2025)","lead_investors":"Infinity Ventures","participating_investors":["JPMorganChase","Nyca Partners","Cross River Digital Ventures","TTV Capital","Third Prime Capital"]},"milestones":["Reported a 3x increase in revenue and client base throughout 2024.","Established multi-year partnerships with major financial institutions including Chime, Upgrade, Pathward, and Varo Bank.","Integrated with risk platforms like Oscilar to provide embedded fairness tools to their customer networks.","Currently serves over 25 banks and fintechs, managing fairness for billions in loan volume."]},"problem_statement":{"core_issue":"The 'Black Box' Bias Problem: As banks move to AI-driven underwriting, they risk inheriting historical biases that lead to unfair rejection of protected classes.","barriers":["Regulatory Pressure: Agencies like the CFPB and regulators under SR 11-7 require AI models to be transparent, explainable, and fair.","Manual Inefficiency: Traditional fair-lending audits take months and are based on 'batch' data rather than real-time monitoring.","The 'Second Look' Gap: Lenders often lack an automated way to re-evaluate 'near-miss' applicants who are creditworthy but flagged by biased algorithms."]},"solution":{"primary_product":"Fairness-as-a-Service™ Platform","key_features":["Automated Bias Testing: APIs that back-test and monitor models in real-time to identify disparate impacts on protected groups.","Second-Look Underwriting: An automated system that re-underwrites declined applications to find creditworthy borrowers the primary model missed.","SR 11-7 Compliance: Auto-generates regulatory-ready documentation, cutting validation cycles from months to days.","Agentic AI Validation: Independent evaluation tools for AI agents to ensure they remain safe and compliant in financial environments.","Fairness Optimization: Proprietary 'loss functions' that teach models to maximize approvals while minimizing disparity during the training phase."],"value_proposition":"Enabling financial institutions to increase approval rates (typically 10-20%) and revenue without increasing risk, all while maintaining perfect regulatory compliance."},"parsing_json":{"company_overview":{"company_name":"FairPlay AI"},"problem":{"problem_statement":"The 'Black Box' Bias Problem: As banks move to AI-driven underwriting, they risk inheriting historical biases that lead to unfair rejection of protected classes.\n\nRegulatory Pressure: Agencies like the CFPB and regulators under SR 11-7 require AI models to be transparent, explainable, and fair.\nManual Inefficiency: Traditional fair-lending audits take months and are based on 'batch' data rather than real-time monitoring.\nThe 'Second Look' Gap: Lenders often lack an automated way to re-evaluate 'near-miss' applicants who are creditworthy but flagged by biased algorithms."},"solution":{"solution_summary":"Fairness-as-a-Service™ Platform\n\nAutomated Bias Testing: APIs that back-test and monitor models in real-time to identify disparate impacts on protected groups.\nSecond-Look Underwriting: An automated system that re-underwrites declined applications to find creditworthy borrowers the primary model missed.\nSR 11-7 Compliance: Auto-generates regulatory-ready documentation, cutting validation cycles from months to days.\nAgentic AI Validation: Independent evaluation tools for AI agents to ensure they remain safe and compliant in financial environments.\nFairness Optimization: Proprietary 'loss functions' that teach models to maximize approvals while minimizing disparity during the training phase.\n\nEnabling financial institutions to increase approval rates (typically 10-20%) and revenue without increasing risk, all while maintaining perfect regulatory compliance."}},"thesis_fit_json":{"overall_thesis_alignment_reasoning":"FairPlay AI — thesis fit (historical corpus, invested).\n\nProblem (The 'Black Box' Bias Problem: As banks move to AI-driven underwriting, they risk inheriting hist…): The 'Black Box' Bias Problem: As banks move to AI-driven underwriting, they risk inheriting historical biases that lead to unfair rejection of protected classes.\n\nRegulatory Pressure: Agencies like the CFPB and regulators under SR 11-7 require AI models to be transparent, explainable, and fair.\nManual Inefficiency: Traditional fair-lending audits take months and are based on 'batch' data rather than real-time monitoring.\nThe 'Second Look' Gap: Lenders often lack an automated way to re-evaluate 'near-miss' applicants who are creditworthy but flagged by biased algorithms.\n\nSolution direction: Fairness-as-a-Service™ Platform\n\nAutomated Bias Testing: APIs that back-test and monitor models in real-time to identify disparate impacts on protected groups.\nSecond-Look Underwriting: An automated system that re-underwrites declined applications to find creditworthy borrowers the primary model missed.\nSR 11-7 Compliance: Auto-generates regulatory-ready documentation, cutting validation cycles from months to days.\nAgentic AI Validation: Independent evaluation tools for AI agents to ensure they remain safe and compliant in financial environments.\nFairness Optimization: Proprietary 'loss functions' that teach models to maximize approvals while minimizing disparity during the training phase.\n\nEnabling financial institutions to increase approval rates (typically 10-20%) and revenue without increasing risk, all while maintaining perfect regulatory compliance.\n\nInstitutional context: Venture (stage per corpus) financing profile ($10 Million (February 2025) · $24.5 Million); team and milestones are consistent with a venture-scale wedge and repeatable GTM.\n\nWhy this cleared the bar at the time: clear buyer pain, differentiated product narrative versus incumbents, and execution depth we could underwrite at the seed mark.","fit_summary":"Strong fit — FairPlay AI is recorded as invested in the markdown corpus.","industry_evaluation":{"startup_industry":"The 'Black Box' Bias Problem: As banks move to AI-driven underwriting, they risk inheriting hist…","score":8.2},"stage_evaluation":{"stage":"Venture (stage per corpus)","score":7.8},"funding_evaluation":{"funding":"$10 Million (February 2025) · $24.5 Million","score":8}},"founder_signal_json":{"per_founder":[{"name":"Kareem Saleh","role":"Founder & CEO","background":"Former executive at Zest.ai and SoftCard; served in the Obama Administration managing international investment teams.","founder_name":"Kareem Saleh"},{"name":"John Merrill","role":"Co-founder & Principal Scientist","background":"Mathematician and AI expert; previously a lead scientist at Zest.ai and spent 15 years at Microsoft and Google building ML tools.","founder_name":"John Merrill"}],"collective":{"founding_team":{"key_personnel":[{"name":"Patrick Cadic","role":"COO","background":"Experienced operations leader in fintech and high-growth startups."},{"name":"Abby Hogan","role":"SVP of Legal Affairs","background":"Specialist in regulatory compliance and fair lending law."},{"name":"Mark Eberstein","role":"EVP of Data Science","background":"Expert in algorithmic fairness and statistical modeling."}],"team_composition":"The team includes veterans from Microsoft, Google, PayPal, and Goldman Sachs, specializing in AI safety, regulatory law, and consumer finance."},"founders":[{"name":"Kareem Saleh","role":"Founder & CEO","background":"Former executive at Zest.ai and SoftCard; served in the Obama Administration managing international investment teams."},{"name":"John Merrill","role":"Co-founder & Principal Scientist","background":"Mathematician and AI expert; previously a lead scientist at Zest.ai and spent 15 years at Microsoft and Google building ML tools."}],"signal_interpretation":{"founder_signal_summary":"The FairPlay AI team lists 2 named leaders with complementary operating and technical depth.\n\nPer-founder roster (summary):\nKareem Saleh — Founder & CEO — Former executive at Zest.ai and SoftCard; served in the Obama Administration managing international investment teams.\nJohn Merrill — Co-founder & Principal Scientist — Mathematician and AI expert; previously a lead scientist at Zest.ai and spent 15 years at Microsoft and Google building ML tools.\n\nDiligence focus: verify prior operating scale (revenue / mandate), hiring velocity, domain-specific proof points, and cohesion between GTM and technical leads; cross-check claims against references and attributed public sources.","team_evidence":{"high_bar_previous_employers":"Prior employers and titles are listed per founder in the corpus.","technical_authority_proof":"Technical authority inferred from roles and prior companies.","team_cohesion_signals":"See founding team narrative in corpus."}}},"summary_text":"Kareem Saleh — Founder & CEO — Former executive at Zest.