INSERT INTO public.deal_pipeline_json_problem_3c (deal_id, analysis_id, problem_quality_3c_json)
VALUES ('1a000000-0000-4000-8000-000000000008'::uuid, '1b000000-0000-4000-8000-000000000008'::uuid, $j${"summary_text":"The insurance claims industry is facing a massive 'labor cliff' where adjusters are retiring faster than they can be replaced, leading to service delays and burnout.\n\nFragmented Communication: Adjusters spend 60% of their time on 'phone tag' and routine status updates.\nUnstructured Data: Sifting through thousands of PDFs, medical bills, and photos manually is slow and error-prone.\nLegacy Systems: Most carriers use 20-year-old Claims Management Systems (CMS) that lack modern automation capabilities.","root_cause_depth":"The insurance claims industry is facing a massive 'labor cliff' where adjusters are retiring faster than they can be replaced, leading to service delays and burnout.","economic_gravity":"The insurance claims industry is facing a massive 'labor cliff' where adjusters are retiring faster than they can be replaced, leading to service delays and burnout.\n\nFragmented Communication: Adjusters spend 60% of their time on 'phone tag' and routine status updates.\nUnstructured Data: Sifting through thousands of PDFs, medical bills, and photos manually is slow and error-prone.\nLegacy Systems: Most carriers use 20-year-old Claims Management Systems (CMS) that lack modern automation capabilities.","structural_urgency":"The insurance claims industry is facing a massive 'labor cliff' where adjusters are retiring faster than they can be replaced, leading to service delays and burnout.\n\nFragmented Communication: Adjusters spend 60% of their time on 'phone tag' and routine status updates.\nUnstructured Data: Sifting through thousands of PDFs, medical bills, and photos manually is slow and error-prone.\nLegacy Systems: Most carriers use 20-year-old Claims Management Systems (CMS) that lack modern automation capabilities.","persona_clarity":null,"stated_problem_ref":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET problem_quality_3c_json = EXCLUDED.problem_quality_3c_json;

INSERT INTO public.deal_pipeline_json_solution_3d (deal_id, analysis_id, solution_defensibility_json)
VALUES ('1a000000-0000-4000-8000-000000000008'::uuid, '1b000000-0000-4000-8000-000000000008'::uuid, $j${"summary_text":"AI-Native Claims Operations Platform\n\nMultimodal AI Agents: Autonomous agents that handle phone calls (intake/status), email triage, and document parsing (extracting data from medical reports).\nEnd-to-End Orchestration: Moves a claim from initial report to settlement without requiring manual data entry at every step.\nWrite-Back Integration: Plugs directly into legacy CMS platforms to keep records updated in real-time.\nLiability Copilot: Analyzes policy terms and flags potential exposures for adjusters to review, ensuring consistency in decisions.\n\nTransforming claims from a manual cost center into a high-speed, automated operation that allows human adjusters to focus on high-stakes decision-making.","moat_type":null,"replication_difficulty":null,"compounding_potential":null,"technical_moat_evidence":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET solution_defensibility_json = EXCLUDED.solution_defensibility_json;

