VALUES ('1a000000-0000-4000-8000-000000000009'::uuid, '1b000000-0000-4000-8000-000000000009'::uuid, $j${"inferred_context":{"funding":{"total_funding":"$500,000+","latest_round":"Y Combinator (Winter 2026 / Fall 2025)","lead_investor":"Y Combinator"},"business_metrics":["Over 400 businesses (restaurants and retail shops) onboarded within the first 6 months of operation.","Achieved 11+ hours saved per week on reconciliation for early adopters.","Reports a 32% increase in captured reservations for clients using their AI voice agents.","Standardized transaction fee of 0.79%, positioning themselves as the low-cost leader compared to Square and SumUp."]},"summary_text":"Funding: Y Combinator (Winter 2026 / Fall 2025) · $500,000+ · Y Combinator\nBusiness metrics:\n• Over 400 businesses (restaurants and retail shops) onboarded within the first 6 months of operation.\n• Achieved 11+ hours saved per week on reconciliation for early adopters.\n• Reports a 32% increase in captured reservations for clients using their AI voice agents.\n• Standardized transaction fee of 0.79%, positioning themselves as the low-cost leader compared to Square and SumUp.","signal_completeness":"historical_seed"}$j$::jsonb)
