INSERT INTO public.deal_pipeline_json_problem_3c (deal_id, analysis_id, problem_quality_3c_json)
VALUES ('1a000000-0000-4000-8000-000000000009'::uuid, '1b000000-0000-4000-8000-000000000009'::uuid, $j${"summary_text":"Small and medium-sized restaurants are currently forced to manage a 'chaos stack' of disconnected tools.\n\nFragmented Systems: Separate providers for POS, reservations, payments, and marketing that do not communicate.\nAdministrative Burden: Owners spend hours on manual reconciliation, menu updates, and staff scheduling.\nMissed Revenue: Inefficient reservation systems lead to missed calls and empty tables during peak hours.","root_cause_depth":"Small and medium-sized restaurants are currently forced to manage a 'chaos stack' of disconnected tools.","economic_gravity":"Small and medium-sized restaurants are currently forced to manage a 'chaos stack' of disconnected tools.\n\nFragmented Systems: Separate providers for POS, reservations, payments, and marketing that do not communicate.\nAdministrative Burden: Owners spend hours on manual reconciliation, menu updates, and staff scheduling.\nMissed Revenue: Inefficient reservation systems lead to missed calls and empty tables during peak hours.","structural_urgency":"Small and medium-sized restaurants are currently forced to manage a 'chaos stack' of disconnected tools.\n\nFragmented Systems: Separate providers for POS, reservations, payments, and marketing that do not communicate.\nAdministrative Burden: Owners spend hours on manual reconciliation, menu updates, and staff scheduling.\nMissed Revenue: Inefficient reservation systems lead to missed calls and empty tables during peak hours.","persona_clarity":null,"stated_problem_ref":null,"signal_completeness":"historical_seed"}$j$::jsonb)
