INSERT INTO public.deal_pipeline_json_solution_3d (deal_id, analysis_id, solution_defensibility_json)
VALUES ('1a000000-0000-4000-8000-000000000009'::uuid, '1b000000-0000-4000-8000-000000000009'::uuid, $j${"summary_text":"AI-Native Operating System for Hospitality\n\nUnified POS & Payments: A single platform for in-person card terminals, online ordering, and Tap to Pay.\nZavo Voice Agents: AI agents that answer the phone, handle reservations, and answer customer queries autonomously.\nAgentic Menu Management: AI that allows staff to make instant menu edits or inventory queries via voice/text.\nAutomated Marketing: AI-driven loyalty campaigns that trigger based on customer spending patterns without manual input.\n\nGiving every independent restaurant its own 'digital workforce' to handle the admin and operations, allowing owners to focus entirely on the guest experience.","moat_type":null,"replication_difficulty":null,"compounding_potential":null,"technical_moat_evidence":null,"signal_completeness":"historical_seed"}$j$::jsonb)
ON CONFLICT (analysis_id) DO UPDATE SET solution_defensibility_json = EXCLUDED.solution_defensibility_json;

